import{_ as o,l,o as e,c as n,v as t,p as s,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"TCB 最小化","description":"","frontmatter":{"title":"TCB 最小化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcb-minimization.md","filePath":"cs/tcb-minimization.md","lastUpdated":1789023840000}'),h={name:"cs/tcb-minimization.md"};function E(m,a,B,A,T,_){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="tcb-最小化" tabindex="-1">TCB 最小化 <a class="header-anchor" href="#tcb-最小化" aria-label="Permalink to &quot;TCB 最小化&quot;">​</a></h1><div class="epigraph"><p>可信计算基是其正确性被依赖来强制策略的全体。体积越大越不能审。微内核、TEE、语言运行时都在削 TCB；seL4 把削完的核送进形式证明。</p><footer>—— 据 Lampson 对保护；Saltzer 经济机制；对照 Klein et al. seL4</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/defense-in-depth">纵深</a>多层。缺口是<strong>每层的核有多大</strong>。本课 TCB：什么必须对、什么可错。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>巨内核+全部驱动在 TCB。缺口是：下推不可信、验证剩余。HSM/TEE 是削的实例。</p><h3 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h3><p>编译器与硬件也在 TCB，除非另证。</p><p><span class="marginnote">Lampson。SDL 下一课是过程；seL4 是形式化封口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列当前系统 TCB。对照微内核。下一课 SDL，再 seL4。</p>',12)),(e(),s(c,null,{default:i(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E5%AE%89%E5%85%A8%E7%AD%96%E7%95%A5%22%5D%20--%3E%20TCB%5B%22%E5%BF%85%E9%A1%BB%E6%AD%A3%E7%A1%AE%E7%9A%84%E5%9F%BA%22%5D%0A%20%20TCB%20--%3E%20SMALL%5B%22%E8%B6%8A%E5%B0%8F%E8%B6%8A%E5%8F%AF%E5%AE%A1%22%5D%0A%20%20REST%5B%22%E5%9F%BA%E5%A4%96%E7%BB%84%E4%BB%B6%22%5D%20--%3E%20UNTRUST%5B%22%E5%8F%AF%E9%94%99%E5%8F%AF%E9%9A%94%E7%A6%BB%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>纵深的每一预防层都有 TCB。削它才能审。SDL 管如何造，seL4 管如何证。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有系统改写成微内核作业。SDL 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纵深每层都有 TCB。</li><li>体积决定能否审与证。</li><li>隔离把组件移出基。</li><li>下一课 SDL。</li><li>出处：Lampson；Saltzer and Schroeder；Klein et al.（下下课）。</li></ul>',8))])}const f=o(h,[["render",E]]);export{b as __pageData,f as default};
